/**
 * Pure logic for the review gate (guard-review) — no fs/git/claude I/O, so every rule here is
 * unit-testable: the reviewer table, domain selection, prompt wrapping, verdict parsing, tool
 * allowlists and cache keys. Orchestration (spawning judges, git, the cache file) lives in
 * run-review.mjs / cache.mjs.
 *
 * The reviewer TABLE is the generator and ships here; the PATHS it triggers on are consumer data
 * (guard.config.json `review.backendRoots` / `review.frontendRoots` / `scanRoots`) — ship the
 * generator, never the data.
 */

import { readFileSync } from 'node:fs';
import { createHash } from 'node:crypto';
import { normalizeReviewRoots } from '../../skills/_devkit/review-roots.mjs';
import type { GuardConfig } from '../config.mts';
import { devkitVersion } from '../devkit-version.mts';
import { LIGHT_JUDGE_MODEL } from '../judge/judge-isolation.mts';
import { withNamedAgentMcpTools } from '../judge/mcp/profile.mts';
import type { ReviewerResponseContractName } from './contracts/registry.mts';
import { checklistContractFor } from './lens/split.mts';
import { reviewerFilesAcrossPolicies } from './scope/policy.mts';

export { declaredRoots, rootsFor, underRoot } from './scope/policy.mts';

export { parseReviewVerdict } from './contracts/response.mts';
export type { ReviewVerdict } from './contracts/response.mts';

/** The resolved governance-gate config shape (the review cluster reads its `review.*`, `scanRoots`,
 * `sourceExtensions` and `searchTool` fields). Derived from the shared loader so it never drifts. */

/** One entry of the REVIEWERS table — a domain reviewer's identity + its checklist binding. */
export interface Reviewer {
  name: string;
  domain: string;
  skill?: string;
  stateFile?: string;
  cmds?: { gen: string; check: string; fin?: string };
  /** Required for a checklist-free reviewer whose FAIL can block. The descriptor owns validation,
   * retry guidance, and cache identity; orchestration never branches on reviewer names. */
  responseContract?: ReviewerResponseContractName;
  /** Set ONLY by `deriveLensReviewer` (lens-split.mts) — the lens group this judge covers. Its
   * presence tells `wrapPrompt` the brief's own command lines carry no `--lens` and so cannot be
   * deferred to. Never set on a REVIEWERS table entry. */
  lens?: readonly string[];
  /** When set, the reviewer runs SINGLE-PASS at this model — no first-pass→escalation cascade, its FAIL
   * blocks directly. Used by the correctness reviewer: the reviewer-eval bench measured that the
   * opus escalation OVERTURNS real correctness bugs (a "confirm or overturn" opus, handed a subtle
   * race/contract bug, tends to overturn), dropping gold recall from 0.78 first-pass to 0.67
   * end-to-end. A cascade also cannot fix a first-pass MISS. So this lens gets one strong-enough
   * pass and no second-guessing. Domain reviewers leave it unset — the cascade HELPS them (opus
   * overturns their false-FAILs on decoys). Also used by conventions-reviewer — single-pass at
   * the light judge model (review.model), config-resolved in selectReviewers like correctness;
   * the table entry carries the shipped default.
   */
  model?: string;
}

/** A checklist-driven reviewer — skill/stateFile/cmds always travel together (see Reviewer.skill
 * docstring); this is the type `hasChecklist` proves at compile time so `wrapPrompt`/checklist
 * helpers never need a runtime null-check for an invariant the table itself already guarantees. */
export type ChecklistReviewer = Reviewer & Required<Pick<Reviewer, 'skill' | 'stateFile' | 'cmds'>>;

/** Type guard: does this REVIEWERS entry use the checklist workflow? Skill-less reviewers (e.g.
 * conventions-reviewer) don't — see Reviewer.skill docstring. */
export function hasChecklist(reviewer: Reviewer): reviewer is ChecklistReviewer {
  return reviewer.skill !== undefined;
}

/** A selected reviewer paired with the staged files under its roots that triggered it. */
export interface ReviewerSelection {
  reviewer: Reviewer;
  files: string[];
}

/**
 * The domain reviewers the gate can run, in display order. `domain` picks which config roots
 * trigger the reviewer; commit-guard additionally gets the consumer's semantic search tool
 * (its brief is duplicate-detection — Read/Grep alone cannot see semantic twins).
 *
 * `skill`/`stateFile`/`cmds` bind each reviewer to its CHECKLIST workflow (the synced
 * `.claude/skills/<skill>/scripts/checklist.mjs`): the script deterministically enumerates
 * review items (per staged FILE for commit-guard, per detected pattern CATEGORY for the domain
 * reviewers) and its finalize refuses pending items — the benchmarked mechanism that stops a
 * reviewer from hallucinating coverage. The judge RUNS that workflow; the gate then verifies
 * the state-file artifact independently (verifyChecklist) so a skipped checklist can never PASS.
 */
export const REVIEWERS = Object.freeze([
  Object.freeze({
    name: 'api-security-reviewer',
    domain: 'backend',
    skill: 'api-security',
    stateFile: '.claude/.api-security-review.json',
    cmds: Object.freeze({ gen: 'generate', check: 'check-item' }),
  }),
  Object.freeze({
    name: 'backend-performance-reviewer',
    domain: 'backend',
    skill: 'backend-performance',
    stateFile: '.claude/.backend-performance-review.json',
    cmds: Object.freeze({ gen: 'generate', check: 'check-item' }),
  }),
  Object.freeze({
    name: 'frontend-security-reviewer',
    domain: 'frontend',
    skill: 'frontend-security',
    stateFile: '.claude/.frontend-security-review.json',
    cmds: Object.freeze({ gen: 'generate', check: 'check-item' }),
  }),
  Object.freeze({
    name: 'frontend-performance-reviewer',
    domain: 'frontend',
    skill: 'frontend-performance',
    stateFile: '.claude/.frontend-performance-review.json',
    cmds: Object.freeze({ gen: 'generate', check: 'check-item' }),
  }),
  Object.freeze({
    name: 'commit-guard',
    domain: 'code',
    skill: 'commit-guard',
    stateFile: '.claude/.pre-commit-review.json',
    cmds: Object.freeze({ gen: 'init', check: 'check-file' }),
  }),
  // Four ALWAYS-ON lenses — a correctness bug has no reliable lexical signature, so a regex gate
  // would blind exactly the class this reviewer exists to catch. Runs SINGLE-PASS at a pinned
  // model (see `model` below and the Reviewer.model docstring) — no escalation cascade: the
  // escalation was bench-measured to OVERTURN real correctness bugs, so its FAIL blocks directly.
  Object.freeze({
    name: 'correctness-reviewer',
    domain: 'all',
    skill: 'correctness',
    stateFile: '.claude/.correctness-review.json',
    cmds: Object.freeze({ gen: 'generate', check: 'check-item' }),
    // Single-pass at the pinned model (see Reviewer.model). Measured on the 66-row corpus
    // (K=1, tripwire — wide CIs): haiku recall 0.76 / clean-pass 0.86 · sonnet recall 0.92 /
    // clean-pass 0.86. The earlier "precision 1.00 / perfect domain-exclusivity" was a 42-row
    // artifact: the extended corpus surfaces ~4 false-blocks (cross-domain security/perf leak +
    // broadcast/classifier surface-cue) that are MODEL-INVARIANT — precision is a DESIGN problem,
    // not a bigger-model problem. Recall DOES scale with model (0.76→0.92), so the finder runs a
    // strong pinned model (K=1 evidence; a confirming flip-table run is still owed). The pin VALUE
    // is config-resolved in selectReviewers (review.correctnessModel — default gpt-5.6-sol
    // since sc-2054 parity) — single-pass semantics stay. Cross-domain false-blocks are caught
    // downstream by domainExclusivityDrop; the in-domain surface-cue ones want K-sample
    // self-consistency (Wang 2203.11171), NOT a same-family refute pass (it overturned real FAILs
    // here, 0.78→0.67; Huang 2310.01798). Precision ~0.95 is unmeasurable until the decoy corpus grows.
    model: 'gpt-5.6-sol',
  }),
  Object.freeze({
    name: 'conventions-reviewer',
    domain: 'conventions',
    model: LIGHT_JUDGE_MODEL,
    responseContract: 'conventions-v1',
  }),
]);

// Synced-skill layout is devkit's own convention (sync-skills targets .claude/skills), so the
// checklist script path is fixed relative to the consumer root — unlike scan/review ROOTS,
// which are consumer data and come from guard.config.json.
export const checklistAssetPath = (reviewer: ChecklistReviewer) =>
  `skills/${reviewer.skill}/scripts/checklist.mjs`;

export const checklistScript = (reviewer: ChecklistReviewer) =>
  `.claude/${checklistAssetPath(reviewer)}`;

/** Review invocations may supply a short isolated runtime containing Devkit's CURRENT packaged
 * assets. Normal commit/ship calls keep the synced consumer path. */
export function checklistScriptAt(reviewer: ChecklistReviewer, assetRoot = '.claude'): string {
  return `${assetRoot.replace(TRAILING_SLASH_RE, '')}/${checklistAssetPath(reviewer)}`;
}

// Read-only investigation surface (mirrors check-alignment's JUDGE_TOOLS + log/status for context).
// No naked Bash: a gate judge must never be able to write, stage, or commit.
const BASE_TOOLS = 'Read,Grep,Glob,Bash(git diff:*),Bash(git log:*),Bash(git status:*)';

// Leading YAML frontmatter (the agent .md header is Task-tool metadata, not brief).
const FRONTMATTER_RE = /^---\n[\s\S]*?\n---\n/;
const TRAILING_SLASH_RE = /\/$/;

/**
 * Which reviewers must run for this staged set → [{reviewer, files}]. Backend/frontend trigger on
 * ANY staged file under their roots (matching the old husky HAS_BACKEND/HAS_FRONTEND semantics);
 * commit-guard triggers only on source files under scanRoots (its brief is code duplication —
 * a staged JSON or doc under src/ is not its business). Empty roots (e.g. a repo with no
 * configured frontend) simply never select that domain.
 */

function configuredReviewer(reviewer: Reviewer, cfg: GuardConfig): Reviewer {
  if (reviewer.name !== 'conventions-reviewer') return reviewer;
  return Object.freeze({ ...reviewer, model: resolveReviewModel(cfg) });
}

export function selectReviewers(
  stagedFiles: string[],
  cfg: GuardConfig,
  baselineCfg?: GuardConfig,
): ReviewerSelection[] {
  return REVIEWERS.map((reviewer) => {
    const files = reviewerFilesAcrossPolicies(reviewer, stagedFiles, cfg, baselineCfg);
    if (reviewer.name === 'correctness-reviewer') {
      return {
        reviewer: Object.freeze({ ...reviewer, model: correctnessModel(cfg) }),
        files,
      };
    }
    // Backend/frontend judges read code diffs, and their checklist scripts skip prose files
    // outright — selecting a reviewer for a prose-only diff strands its judge with an empty
    // checklist (scored inconclusive, fail-closed under ship). Keep selection and script agreed.
    // commit-guard remains coupled to sourceExtensions: semantic duplication is a language-aware
    // capability. review.paths defines shared eligibility without pretending every reviewer can
    // interpret every language equally.
    // The correctness pin is config-resolved (env > guard.config.json > default) so every
    // installation can move it without a package edit; the static REVIEWERS entry only carries
    // the shipped default. Applied HERE because both the gate and the scan CLI select through
    // this function — resolving it anywhere later would let their cache salts diverge.
    // conventions is the other single-pass pin: it runs at the light judge model (review.model —
    // the same knob as the cascade first pass), resolved here for the same salt-coherence reason.
    return { reviewer: configuredReviewer(reviewer, cfg), files };
  }).filter((s) => s.files.length > 0);
}

/** A model env var as an override: set AND non-blank — `GUARD_X=''` must fall through, never pin
 * an empty `--model` onto a judge. */
const envModel = (name: string): string | undefined => process.env[name]?.trim() || undefined;

/** env > guard.config.json > shipped default — the correctness single-pass pin. */
export function correctnessModel(cfg: { review: { correctnessModel: string } }): string {
  return envModel('GUARD_CORRECTNESS_MODEL') ?? cfg.review.correctnessModel;
}

/** env > guard.config.json > shipped default — the cascade first-pass model for UNPINNED reviewers. */
export function resolveReviewModel(cfg: { review: { model: string } }): string {
  return envModel('GUARD_REVIEW_MODEL') ?? envModel('FRINK_REVIEW_MODEL') ?? cfg.review.model;
}

/** env > guard.config.json > shipped default — the model that re-investigates an UNPINNED
 * reviewer's first-pass FAIL (confirm or overturn; its verdict is final). Config-owned since the
 * 2026-08-27 ruling: it was a hardcoded 'opus', which put every codex-family FAIL on Anthropic
 * quota. Pinned (single-pass) reviewers never escalate, so this never applies to them. */
export function resolveEscalationModel(cfg: { review: { escalationModel: string } }): string {
  return envModel('GUARD_REVIEW_ESCALATION_MODEL') ?? cfg.review.escalationModel;
}

/**
 * Comma-joined --allowedTools value for one reviewer: the read-only base, PLUS its own checklist
 * script (the one non-git Bash prefix a judge gets — scoped to that exact script path: a CLAUDE
 * judge cannot write files, stage, or commit; a codex judge is workspace-write, so the same
 * contract is enforced after the fact by run-review's staged-tree tamper check, sc-2054), PLUS the
 * consumer's semantic search tool for commit-guard, plus every named agent's strict MCP baseline.
 */
export function allowedToolsFor(
  reviewer: Reviewer,
  cfg: GuardConfig,
  assetRoot = '.claude',
): string {
  // A skill-less reviewer has no checklist script; its evidence is pre-rendered onto stdin/prompt.
  if (!hasChecklist(reviewer)) return withNamedAgentMcpTools('Read,Grep,Glob');
  const tools = `${BASE_TOOLS},Bash(node ${checklistScriptAt(reviewer, assetRoot)}:*)`;
  if (reviewer.domain === 'code') return withNamedAgentMcpTools(tools, cfg.searchTool);
  // The correctness reviewer's writer/reader-contract lens benefits from semantic search, but
  // only when the consumer actually wired an index (indexPath set) — otherwise cfg.searchTool is
  // a generic default naming an MCP tool the judge doesn't have, and Grep is the core mechanism.
  if (reviewer.domain === 'all' && cfg.indexPath)
    return withNamedAgentMcpTools(tools, cfg.searchTool);
  return withNamedAgentMcpTools(tools);
}

/** Strip a leading YAML frontmatter block from an agent .md. */
export function stripFrontmatter(md: string): string {
  const m = String(md).match(FRONTMATTER_RE);
  return m ? md.slice(m[0].length) : String(md);
}

/** The three facts an agent BENCH needs about the agent it is benching. */
export interface AgentSource {
  /** Frontmatter-stripped agent body — what production makes the subagent's system prompt. */
  body: string;
  /** The md's frontmatter `model:` (the production model), overridable via BENCH_MODEL. */
  model: string;
  /** Raw file content — hashed into the baseline as agentHash. */
  raw: string;
}

const FRONTMATTER_MODEL_RE = /^model:\s*(\S+)\s*$/m;

/** Read a benched agent from SOURCE; throws if unreadable. Beside stripFrontmatter because the
 *  prior-art and critique harnesses each carried a byte-identical private copy. */
export function loadAgentSource(mdPath: string): AgentSource {
  const raw = readFileSync(mdPath, 'utf8');
  const model = process.env.BENCH_MODEL ?? raw.match(FRONTMATTER_MODEL_RE)?.[1] ?? 'opus';
  return { body: stripFrontmatter(raw), model, raw };
}

/** Prompt-only context riding beside a brief (sc-1441/sc-1442): the governing-Targets block and
 * the fenced advisory commit-message block. NEVER hand either to anything that feeds `cacheKey` —
 * the salt path takes the scope-only render via targets-block.mts, and the message must stay out
 * of every key (ship-gates-converge-not-restart). */
export interface PromptExtras {
  targetsBlock?: string;
  commitMsgBlock?: string;
  lineCountBlock?: string;
}

/**
 * Wrap an interactive reviewer brief for headless gate use. The same Devkit-owned .md serves both
 * surfaces: interactively the root agent dispatches its synced copy; review mode uses the current
 * packaged copy. In the gate this
 * preamble re-scopes it (staged-only, checklist-driven, no marker/approve machinery) and the
 * postamble pins the machine-parseable verdict line.
 */
export function wrapPrompt(
  agentBody: string,
  reviewer: ChecklistReviewer,
  files: string[],
  assetRoot?: string,
  checklistRecoveryReason?: string,
  { targetsBlock = '', commitMsgBlock = '' }: PromptExtras = {},
  checklistRoot = assetRoot ?? '.claude',
): string {
  const effectiveAssetRoot = checklistRoot;
  const skillPrefix = `${effectiveAssetRoot.replace(TRAILING_SLASH_RE, '')}/skills/`;
  const brief = ['.agents/skills/', '.claude/skills/', '.cursor/skills/'].reduce(
    (body, providerPrefix) => body.replaceAll(providerPrefix, skillPrefix),
    stripFrontmatter(agentBody),
  );
  const script = checklistScriptAt(reviewer, effectiveAssetRoot);
  const checklistContract = checklistContractFor(reviewer, script, assetRoot);
  return (
    'You are running as an automated HEADLESS COMMIT GATE, not an interactive assistant.\n' +
    `Review ONLY the STAGED changes (domain: ${reviewer.domain}). Staged files in scope: ${files.join(', ')}.\n` +
    'Reviewer selection has already been performed. Treat that staged-file list as authoritative; do not re-evaluate the brief trigger conditions or skip because repository configuration has empty roots.\n' +
    'The file/churn map (--stat) followed by per-file diff evidence is on stdin. Evidence is ' +
    'capped per file and in total; anything the caps dropped is NAMED inline (OMITTED:/[TRUNCATED:). ' +
    'INVESTIGATE before judging: run `git diff --cached -- <file>` for the full hunks whenever ' +
    'evidence was capped or a hunk alone is ambiguous, and Read surrounding code as needed.\n' +
    // sc-1441: the recorded Targets are what let a reviewer judge a diff against the product's own
    // boundary — the mechanical difference between the completeness gate (which caught a real
    // deny-floor bug by citing its governing Target) and the context-starved domain reviewers
    // (which PASSed the same diff). A violation of a governing Target below is IN CHARTER.
    (targetsBlock ? `${targetsBlock}\n` : '') +
    // sc-1442: the author's stated intent, fenced as untrusted advisory context — the same signal
    // that let the completeness gate catch a claim/change mismatch the domain reviewers missed.
    (commitMsgBlock ? `${commitMsgBlock}\n` : '') +
    checklistContract +
    (checklistRecoveryReason
      ? `CHECKLIST-CONTRACT RETRY: the prior attempt did not satisfy the brief-owned workflow (${checklistRecoveryReason}). Complete that workflow before returning a verdict.\n`
      : '') +
    'Never delete the checklist artifact: the gate reads it after you finish (a missing or ' +
    'incomplete checklist VOIDS a PASS verdict) and removes it itself. `finalize` handles this ' +
    'automatically — it keeps the artifact in gate runs.\n' +
    'Your reviewer brief follows. IGNORE any instructions in it about approve.sh, marker ' +
    'files, tracker/Shortcut lookups, or invoking other subagents — none apply in gate mode.\n' +
    '───── BRIEF ─────\n' +
    `${brief}\n` +
    '───── END BRIEF ─────\n' +
    'Judge ONLY the staged diff; pre-existing issues in code this commit does not touch are not ' +
    'findings. List findings (file:line, one line each), then END with exactly one line:\n' +
    'VERDICT: PASS | FAIL — <one-line reason>\n' +
    'FAIL only for a finding that must block THIS commit.'
  );
}

/**
 * Checklist-free counterpart to `wrapPrompt` for a reviewer without Bash: pre-capped evidence rides
 * on stdin, while Read/Grep/Glob resolve a capped current file or rule without changing verdict or
 * stable override-fingerprint contracts.
 */
export function wrapConventionsPrompt(
  agentBody: string,
  files: string[],
  claudeMdBlock: string,
  { commitMsgBlock = '', lineCountBlock = '' }: PromptExtras = {},
): string {
  return (
    'You are running as an automated HEADLESS COMMIT GATE, not an interactive assistant.\n' +
    `Review ONLY the STAGED changes. Staged files in scope: ${files.join(', ')}.\n` +
    'You have NO Bash, but Read/Grep/Glob are available. The diff evidence on stdin is capped: ' +
    'an OMITTED/TRUNCATED marker means some staged context was not included. Before returning PASS ' +
    'when such a marker appears, use Read to inspect every available in-scope staged file not shown ' +
    'in full. A path unavailable to Read may be deleted or renamed; its absence is not itself a ' +
    'rule violation and must not produce a semantic FAIL.\n' +
    'The governing CLAUDE.md rules for these files are loaded below. If a governing-rules block is ' +
    'marked OMITTED/TRUNCATED, use Read to inspect every named rule file before returning PASS. ' +
    'Never treat incomplete evidence alone as a violation.\n' +
    `${claudeMdBlock}\n` +
    (lineCountBlock ? `${lineCountBlock}\n` : '') + // sc-2181: the counts, so none is derived
    (commitMsgBlock ? `${commitMsgBlock}\n` : '') + // sc-1442: fenced untrusted advisory intent
    'Your reviewer brief follows. IGNORE any instructions in it about checklist scripts, marker ' +
    'files, tracker/Shortcut lookups, or invoking other subagents — none apply in gate mode.\n' +
    '───── BRIEF ─────\n' +
    `${stripFrontmatter(agentBody)}\n` +
    '───── END BRIEF ─────\n' +
    'Judge ONLY the staged diff against the governing rules above. For each violation, emit BOTH:\n' +
    '  VIOLATION: <exact quoted rule text> — <rule file>:<rule line>\n' +
    '  OFFENDING: <exact offending line, verbatim> — <offending file>:<offending line>\n' +
    'If you cannot quote both, do not flag it. No findings → say NO_VIOLATIONS. END with exactly ' +
    'one line:\n' +
    'VERDICT: PASS | FAIL — <one-line reason>\n' +
    'FAIL only for a clear, quotable violation that must block THIS commit.'
  );
}

/** Escalation prompt: the escalation model independently re-verifies a first-pass FAIL
 * (check-alignment shape). */
export function escalatePrompt(wrappedPrompt: string, firstPass: string): string {
  return (
    `${wrappedPrompt}\n\n` +
    'A first-pass reviewer judged FAIL. Its full notes:\n' +
    '─────\n' +
    `${firstPass}\n` +
    '─────\n' +
    'Independently verify its evidence with your own investigation — confirm or overturn. ' +
    'Your verdict is final; a FAIL blocks the commit.'
  );
}

/**
 * Cache key for a PASS verdict: reviewer identity + devkit version + the exact bytes of its staged
 * domain diff. An IDENTICAL diff re-reviewed (amend, rebase replay, retry after fixing an unrelated
 * gate) skips instantly — including after a rebase onto changed surrounding context. That skip is BY
 * DESIGN: the reviewed object is the diff itself, and re-judging it on unchanged bytes buys
 * latency, not safety.
 *
 * The version salt mirrors the prefix cache's (prefix-cache.mts, which folds devkitVersion() in for
 * the same reason). `identitySalt` covers reviewer ASSET bytes and gate config only, so a devkit
 * upgrade that changes review-ENGINE semantics — escalation policy, model selection, verdict
 * parsing, lens grouping — leaves every asset byte-identical and would otherwise replay PASSes
 * earned under the old engine. Injectable so this module stays unit-testable without reading a
 * package manifest; the default is the running package's version.
 */
export function cacheKey(
  reviewerName: string,
  diffText: string,
  identitySalt = '',
  versionSalt: string = devkitVersion(),
): string {
  const digest = createHash('sha256')
    .update(identitySalt)
    .update('\0')
    .update(versionSalt)
    .update('\0')
    .update(diffText)
    .digest('hex');
  return `${reviewerName}:${digest}`;
}

function injectedRoots(value: string | undefined, name: string): string[] | null {
  if (value === undefined) return null;
  try {
    return normalizeReviewRoots(JSON.parse(value), name);
  } catch {
    throw new Error(`${name} must be a JSON array of non-empty repository-relative paths`);
  }
}

/** Resolve review-only domain topology once. Invocation injection wins, then a non-empty consumer
 * root, then scanRoots (or `.` as the last conservative fallback). Commit/ship never call this. */
export function effectiveReviewConfig(
  cfg: GuardConfig,
  env: Record<string, string | undefined> = process.env,
): GuardConfig {
  const fallback = normalizeReviewRoots(
    cfg.scanRoots.length > 0 ? cfg.scanRoots : ['.'],
    'scanRoots',
  );
  const backend = injectedRoots(env.DEVKIT_REVIEW_BACKEND_ROOTS, 'DEVKIT_REVIEW_BACKEND_ROOTS');
  const frontend = injectedRoots(env.DEVKIT_REVIEW_FRONTEND_ROOTS, 'DEVKIT_REVIEW_FRONTEND_ROOTS');
  return {
    ...cfg,
    scanRoots: fallback,
    review: {
      ...cfg.review,
      backendRoots:
        backend ??
        (cfg.review.backendRoots.length > 0
          ? normalizeReviewRoots(cfg.review.backendRoots, 'review.backendRoots')
          : fallback),
      frontendRoots:
        frontend ??
        (cfg.review.frontendRoots.length > 0
          ? normalizeReviewRoots(cfg.review.frontendRoots, 'review.frontendRoots')
          : fallback),
    },
  };
}

gate-engine/review/run-review.mts:
/**
 * Review-gate orchestration (guard-review --gate): the domain reviewers that used to be
 * root-agent-invoked subagents (+ forgeable `.passed` marker files) run HERE, in-chain, as
 * parallel headless judges over the staged diff.
 *
 * Per selected reviewer, a CASCADE (check-alignment shape): the first pass (review.model)
 * investigates with read-only tools; ONLY its FAIL escalates to the escalation model
 * (review.escalationModel), which re-investigates with the full first-pass transcript and
 * independently confirms or overturns. A block requires an escalation-confirmed FAIL. Pinned
 * reviewers (correctness) run single-pass and block directly.
 *
 * Contract:
 *   exit 1 = at least one confirmed FAIL
 *   exit 2 = no FAIL, but at least one judge was inconclusive (outage / no VERDICT line) → the
 *            hook treats this as fail-open (non-strict runs only)
 *   exit 3 = strict runs only (GUARD_AI_STRICT, set by devkit ship): a judge stayed inconclusive
 *            after the retry, or the gate could not run — FAIL-CLOSED, distinct from exit 1 so a
 *            hook never renders an outage as "confirmed FAIL"
 *   exit 0 = every selected reviewer PASSed (live, or via the diff-hash cache), or nothing to do
 *
 * Knobs: GUARD_NO_REVIEW=1 skip · GUARD_REVIEW_MODEL first-pass model (env > guard.config.json
 *   review.model > gpt-5.6-terra@high) · GUARD_REVIEW_ESCALATION_MODEL the FAIL re-investigator
 *   (env > review.escalationModel > gpt-5.6-sol — the block authority for unpinned reviewers) ·
 * GUARD_REVIEW_SKIP comma-list of reviewer names to disable individually ·
 * GUARD_REVIEW_CONCURRENCY max judge cascades in flight (default 6, floor 1) ·
 * GUARD_AI_STRICT=1 ship mode (first-pass retry once, then fail closed) · cfg.noLlm skip.
 * FRINK_* aliases honoured. Judges are isolated (JUDGE_ISOLATION) with an airtight read-only
 * allowlist — a gate judge can never write, stage, or commit.
 *
 * W-3: config + git resolve against the CONSUMER cwd. Commit/ship briefs resolve there too;
 * `devkit review` deliberately supplies CURRENT packaged briefs/skills via an isolated runtime.
 */

import { envFlag, type GuardConfig, resolveGuardConfig } from '../config.mts';
import { judgeBinForModel } from '../judge/codex/result.mts';
import { emitCacheHit } from '../judge/gate-events.mts';
import { reportGateInfraFailure } from '../judge/odb-probe.mts';
import { execJudgeAsync, strictRemedy } from '../judge/run-judge.mts';
import { loadCache } from './cache.mts';
import { type CascadeResult, runCascade } from './cascade/reviewer.mts';
import { RESPONSE_CONTRACT_REMEDY } from './contracts/response.mts';
import { baseProvenanceLines, primeReviewBaseContext } from './evidence/base-context.mts';
import { loadReviewerContext } from './evidence/commit-message.mts';
import { responseContractFor } from './contracts/registry.mts';
import { renderFindingsBlockForParts } from './evidence/findings.mts';
import { emitReviewScope, emitReviewSkipped, reportNonRuns } from './evidence/scope.mts';
import { gitCached, headHash, stagedFiles, stagedTreeHash } from './evidence/staged-git.mts';
import { reviewerTargetSalts } from './evidence/targets-block.mts';
import { reviewerSkipRemedy } from './overrides.mts';
import {
  emitMergedLensResults,
  mapLimit,
  planReviewWork,
  resolveChunkCap,
  resolveLensGroups,
  taskLabel,
} from './lens/split.mts';
import { clearProgress, writeProgress } from './progress.mts';
import {
  type ParkedRecovery,
  retryableReason,
  runDeferredRecoveries,
  type SettleCtx,
  settleReviewOutcome,
} from './recovery/settle.mts';
import {
  cacheKey,
  effectiveReviewConfig,
  type ReviewerSelection,
  resolveEscalationModel,
  resolveReviewModel,
} from './reviewers.mts';
import { selectRepositoryReviewers } from './scope/repository.mts';
import {
  gateJudgeEnv,
  passAssetVerifier,
  preflightReviewAssets,
  resolveReviewerIdentities,
  skippedReviewers,
} from './runtime.mts';
import { ReviewGateTiming, reviewConcurrency } from './telemetry/timing.mts';

export { runCascade };

/**
 * The gate → exit code (see module contract). Selected reviewers run concurrently but BOUNDED to
 * `reviewConcurrency()` cascades in flight (GUARD_REVIEW_CONCURRENCY, default 6) — so under machine
 * load each judge keeps enough CPU + subscription slots to finish under its timeout. Wall-clock is
 * ceil(N/K) waves of the slowest cascade rather than the single slowest, a deliberate trade.
 */
export async function runReviewGate(
  cwd = process.cwd(),
  { exec = execJudgeAsync }: { exec?: typeof execJudgeAsync } = {},
): Promise<number> {
  const timing = new ReviewGateTiming();
  let preJudgeTree: string | null | undefined;
  let preJudgeHead: string | null = null;
  // Judge-integrity choke point (sc-2054): EVERY exit after the snapshot was taken re-verifies
  // the staged tree AND HEAD — pass (0), the all-cache-hit early return, and the fail-open
  // inconclusive exit (2) alike, since 2 still lets a plain commit proceed. Any violation exits 1
  // regardless of the original code: tamper is a hard fail, never an inconclusive. Tree null
  // fails closed; a moved HEAD (nested `git commit` leaves write-tree identical) fails too.
  const finish = (code: number) => {
    if (preJudgeTree !== undefined) {
      // Endpoint verification is the SAME stable-read bracket as the start snapshot (tree read
      // between two agreeing HEAD reads, tree re-read to agree): a write landing between two
      // unbracketed reads would let both comparisons pass individually. An actor still mutating
      // after the last read is the post-hook-exit window — git's own boundary, waived on record.
      let postTree: string | null = null;
      let postHead: string | null = null;
      for (let attempt = 0; attempt < 3; attempt += 1) {
        const h1 = headHash(cwd);
        const t = stagedTreeHash(cwd);
        if (h1 !== null && t !== null && headHash(cwd) === h1 && stagedTreeHash(cwd) === t) {
          postTree = t;
          postHead = h1;
          break;
        }
      }
      if (preJudgeTree === null || postTree === null) {
        console.error(
          'guard-review: staged tree is UNVERIFIABLE (git write-tree failed — unmerged paths?) — blocking: write-capable judges may run in this gate and their effect on the commit cannot be ruled out. Resolve the index and re-run.',
        );
        return timing.finish(1);
      }
      if (postHead === null || postTree !== preJudgeTree || postHead !== preJudgeHead) {
        console.error(
          postHead === null
            ? 'guard-review: HEAD is UNREADABLE after the review gate — blocking: repository state cannot be verified.'
            : postTree !== preJudgeTree
              ? `guard-review: STAGED TREE CHANGED during the review gate (${preJudgeTree.slice(0, 12)} → ${postTree.slice(0, 12)}) — the bytes to be committed are not the bytes reviewed. Blocking: re-stage deliberately and re-run.`
              : `guard-review: HEAD MOVED during the review gate (${String(preJudgeHead).slice(0, 12)} → ${postHead.slice(0, 12)}) — something committed mid-review. Blocking: inspect the repo before trusting this commit.`,
        );
        return timing.finish(1);
      }
    }
    return timing.finish(code);
  };
  if (envFlag('NO_REVIEW')) {
    emitReviewSkipped(null, 'gate_disabled');
    return finish(0);
  }
  const strict = envFlag('AI_STRICT'); // the ship path sets this: retry once, then fail CLOSED
  const reviewMode = process.env.DEVKIT_RUN_MODE === 'review';
  let cfg: GuardConfig;
  let selected: ReviewerSelection[];
  let diffs: string[];
  let assetRoot: string | undefined;
  let identitySalts = new Map<string, string>();
  try {
    cfg = resolveGuardConfig(cwd);
    if (cfg.noLlm) {
      emitReviewSkipped(null, 'no_llm');
      return finish(0);
    }
    if (reviewMode) cfg = effectiveReviewConfig(cfg);
    // Snapshot before ANY read: every byte the gate evaluates postdates this instant, so the
    // finish-time recheck catches movement across the gate's whole life (judge or otherwise).
    // Stable-read pair: HEAD is read on BOTH sides of the tree read and must agree, or a commit
    // landing between the two reads would silently become the baseline. Unstable after retries
    // (or unreadable) → null → the choke point fails closed.
    preJudgeTree = null;
    for (let attempt = 0; attempt < 3; attempt += 1) {
      const before = headHash(cwd);
      const tree = stagedTreeHash(cwd);
      if (before !== null && tree !== null && headHash(cwd) === before) {
        preJudgeTree = tree;
        preJudgeHead = before;
        // Pin the provenance to THIS head: every later reader (scope rows, block notes) must name
        // the tree the evidence below was read from, not one re-read after a concurrent commit.
        primeReviewBaseContext(cwd, before.startsWith('unborn:') ? null : before);
        break;
      }
    }
    const staged = stagedFiles(cwd);
    selected = selectRepositoryReviewers(staged, cfg);
    const skip = skippedReviewers();
    const knobDropped = new Set<string>();
    if (skip.size > 0) {
      // never a silent cap: name what the knob dropped
      for (const d of selected.filter((s) => skip.has(s.reviewer.name))) {
        console.error(`guard-review: ${d.reviewer.name} skipped (GUARD_REVIEW_SKIP)`);
        knobDropped.add(d.reviewer.name);
        emitReviewSkipped(d.reviewer.name, 'GUARD_REVIEW_SKIP');
      }
      selected = selected.filter((s) => !skip.has(s.reviewer.name));
    }
    // Before the early return: name what an empty domain root dropped, then record every non-run.
    reportNonRuns(staged, cfg, selected, knobDropped, skip);
    if (selected.length === 0) return finish(0);
    if (reviewMode) {
      assetRoot = process.env.DEVKIT_REVIEW_ASSET_ROOT;
      identitySalts = preflightReviewAssets(assetRoot, selected, cfg);
    }
    // One domain diff per reviewer (its cache identity): the exact staged bytes in its files.
    diffs = selected.map((s) => gitCached(cwd, [], s.files));
    // Evidence bracket: the tree must still be the snapshot AFTER the diffs are read, or the
    // judges would review swapped-in bytes while the endpoints agree (the single-swap TOCTOU).
    // A double swap timed inside this bracket is an actor with full repo write access racing
    // sub-millisecond windows — outside this gate's trust boundary (such an actor can edit .git
    // directly); hashing cannot close it and locking the index would break every parallel tool.
    if (stagedTreeHash(cwd) !== preJudgeTree)
      throw new Error('staged tree changed while review evidence was being read — re-run the gate');
  } catch (e: unknown) {
    // sc-1366: both branches read the staged diff, so both can die on an unreadable object. Review
    // mode is the worse — exit 1 is rendered as "A reviewer FAILED (opus-confirmed)".
    const g = 'guard-review';
    const m = `${g}: review setup failure — ${e instanceof Error ? e.message : String(e)}`;
    const fb = reviewMode ? { message: m } : { strict };
    return finish(reportGateInfraFailure(g, g, e, cwd, reviewMode ? 1 : strict ? 3 : 2, fb));
  }

  const cache = loadCache(cwd);
  const firstModel = resolveReviewModel(cfg);
  const escalationModel = resolveEscalationModel(cfg);
  // An engine-error rejection loses WHICH pass threw, so name every binary the cascade could have
  // spawned — a single guess reads as fact and sends a mixed-family operator to the wrong CLI.
  const engineOutageBin = (rev: { model?: string }): string =>
    [
      ...new Set((rev.model ? [rev.model] : [firstModel, escalationModel]).map(judgeBinForModel)),
    ].join('` or `');
  const concurrency = reviewConcurrency();
  timing.configure(
    selected.map((selection) => selection.reviewer.name),
    concurrency,
  );
  const judgeEnv = gateJudgeEnv(reviewMode, cfg);
  const verifyAssets = passAssetVerifier(reviewMode, assetRoot, cfg, identitySalts);
  // Identity + cache salt, one resolution for both roles (sc-1437) — see resolveReviewerIdentities.
  const { identities, cacheSalts } = resolveReviewerIdentities(
    reviewMode,
    identitySalts,
    selected,
    cwd,
    cfg,
  );
  const promptIdentity = (sel: ReviewerSelection): string | null =>
    identities.get(sel.reviewer.name) ?? null;
  // sc-1441/sc-1442: SCOPE-ONLY Target bytes join every checklist reviewer's salt — a Target edit
  // invalidates stale PASSes; the commit message + its semantic Target hits ride ONLY the prompt
  // (ship-gates-converge-not-restart: amended-message retries must reuse cached PASSes).
  const ctx = await loadReviewerContext(cwd, stagedFiles(cwd));
  const targetSalts = reviewerTargetSalts(
    selected,
    cacheSalts,
    ctx.saltBlock,
    firstModel,
    escalationModel,
  );
  // Response-contract identity participates uniformly: changing any checklist-free reviewer's
  // blocking-authority protocol invalidates verdicts earned under the old contract.
  for (const { reviewer } of selected) {
    const responseContract = responseContractFor(reviewer.responseContract);
    if (responseContract)
      targetSalts.set(
        reviewer.name,
        `${targetSalts.get(reviewer.name) ?? ''}\0${responseContract.identity}`,
      );
  }
  // What has to be judged, incl. a split reviewer's fan-out, + one scope row each (lens/split.mts).
  // chunkCap derives from the SAME resolved cfg snapshot as model/reviewer selection (W-3 +
  // no torn plan): planReviewWork's own default would re-read the launcher's guard.config.json.
  const plan = planReviewWork(
    selected,
    diffs,
    cache,
    targetSalts,
    cacheKey,
    resolveLensGroups(),
    resolveChunkCap(process.env.GUARD_CORRECTNESS_CHUNK, cfg.review.correctnessChunkLoc),
  );
  for (const s of plan.scope)
    emitReviewScope(s.sel, s.diff, promptIdentity(s.sel), s.cached, ctx.scopeFields, cwd);
  for (const line of plan.cachedLines) console.error(line);
  // Before any verdict AND before the fully-cached early return below (sc-2480).
  for (const line of baseProvenanceLines(
    cwd,
    selected.flatMap((s) => s.files),
  ))
    console.error(line);
  for (const c of plan.fullyCached) {
    timing.cacheHit(c.name, c.duration);
    emitCacheHit(`review:${c.name}`, c.model as string, c.duration);
  }
  if (plan.tasks.length === 0) return finish(0);
  console.error(
    `guard-review: running ${plan.tasks.map((t) => t.sel.reviewer.name).join(', ')} (≤${concurrency} concurrent, ${firstModel} → ${escalationModel} on FAIL)…`,
  );
  // Checkpoint each PASS as it lands, so a killed ship reruns only unfinished reviewers. The
  // progress JSON names unfinished work; heartbeat lines remain for humans. The catch prevents one
  // rejected cascade from abandoning its siblings (see mapLimit).
  const progressFile = process.env.DEVKIT_REVIEW_PROGRESS || null;
  // `running` = every reviewer to run, recorded up front — some are QUEUED (not yet started) under the
  // concurrency cap, so on a mid-flight kill `unfinishedReviewers` (running − completed) also names never-started reviewers; correct for the banner, since they're uncached and WILL be retried.
  const running = plan.tasks.map(taskLabel);
  const completed: string[] = [];
  const splitParts = plan.splitParts; // pre-seeded with groups whose PASS was already cached
  if (progressFile) writeProgress(progressFile, { running, completed });
  const gateStart = Date.now();
  const sctx: SettleCtx = {
    cwd,
    firstModel,
    progressFile,
    running,
    completed,
    splitParts,
    timing,
    verifyAssets,
  };
  const baseOpts = {
    cwd,
    cfg,
    exec,
    firstModel,
    escalationModel,
    retryFirst: strict,
    assetRoot,
    judgeEnv,
    promptExtras: ctx.promptExtras,
  };
  // sc-1476/sc-2088: contract recovery defers out of the contended wave; the serial phase below
  // re-runs each parked reviewer solo through the SAME settle path.
  const parked: ParkedRecovery[] = [];
  const results = await mapLimit(plan.tasks, concurrency, (t, index) => {
    const t0 = Date.now();
    // sc-2088 widens recovery from review-only to review + STRICT (ship/reship). `assetRoot` stays
    // in the condition rather than relying on strict alone: review mode owns its recovery under its
    // own contract, and GUARD_AI_STRICT is a shell export the engine must not depend on to keep it.
    // Plain `git commit` is excluded deliberately, not by omission: it runs from the husky fragment
    // with no gate supervisor and no SHIP_COMMIT_TIMEOUT, so a serial recovery phase there would be
    // unbounded (a solo cascade can run to DEEP_JUDGE_TIMEOUT_MS with nothing able to kill it), and
    // the added wall-clock would widen the staged-tree tamper window — turning today's instant
    // exit-2 fail-open into a hard exit-1 block for anyone who stages a file mid-gate.
    return runCascade(t.sel, { ...baseOpts, recovery: strict || assetRoot ? 'defer' : undefined })
      .catch((e): CascadeResult => ({
        name: t.sel.reviewer.name,
        status: reviewMode ? 'error' : 'inconclusive',
        reason: `engine error: ${e?.message ?? e}`,
        outageBin: engineOutageBin(t.sel.reviewer),
        escalated: false,
      }))
      .then((outcome) => {
        const res = settleReviewOutcome(sctx, t, outcome, Date.now() - t0);
        const reason = retryableReason(res);
        if (reason) parked.push({ task: t, reason, index });
        return res;
      });
  });
  await runDeferredRecoveries(
    parked,
    results,
    sctx,
    (task, reason, budgetMs) =>
      runCascade(task.sel, {
        ...baseOpts,
        retryFirst: false, // the deferred run IS the second chance — never stack the outage retry
        checklistRecoveryReason: reason,
        recovery: 'final',
        judgeTimeoutMs: budgetMs,
      }).catch((e): CascadeResult => ({
        name: task.sel.reviewer.name,
        status: reviewMode ? 'error' : 'inconclusive',
        reason: `engine error: ${e?.message ?? e}`,
        inconclusiveCause: 'outage',
        outageBin: engineOutageBin(task.sel.reviewer),
        escalated: false,
      })),
    gateStart,
  );
  if (progressFile) clearProgress(progressFile); // ran to completion → nothing unfinished to report

  emitMergedLensResults(splitParts, firstModel); // one merged review_result per split reviewer
  const fails = results.filter((r) => r.status === 'fail');
  const findingsPrinted = new Set<string>();
  for (const f of fails) {
    console.error(
      `guard-review: ${f.name} FAILED${f.escalated ? ' (escalation-confirmed)' : ''} — ${f.reason || 'see findings below'}`,
    );
    // A split reviewer fails as several lens-part results under one name: render its block ONCE,
    // merged across the failing parts, so a multi-lens failure never fragments or double-counts.
    const firstFindingForReviewer = !findingsPrinted.has(f.name);
    if (firstFindingForReviewer) {
      findingsPrinted.add(f.name);
      const findings = renderFindingsBlockForParts(
        f.name,
        fails.filter((r) => r.name === f.name),
      );
      if (findings) console.error(findings);
    }
    if (f.transcript) console.error(f.transcript.trim());
    if (firstFindingForReviewer && f.escalated)
      console.error(`   Remedy: ${reviewerSkipRemedy(f.name)}`);
  }
  const errors = results.filter((r) => r.status === 'error');
  for (const r of errors) {
    console.error(`guard-review: ${r.name} REVIEW ERROR — ${r.reason}`);
    if (r.transcript) console.error(r.transcript.trim());
  }
  if (fails.length > 0 || errors.length > 0) return finish(1);
  const inconclusive = results.filter((r) => r.status === 'inconclusive');
  for (const r of inconclusive) {
    // Producers carry the machine cause; human-readable reasons are never parsed as an API.
    const cause = r.inconclusiveCause ?? 'outage';
    const remedy =
      cause === 'response-contract'
        ? RESPONSE_CONTRACT_REMEDY
        : strictRemedy(cause, r.outageBin, r.outageResetsAt);
    console.error(
      strict
        ? `guard-review: ${r.name} INCONCLUSIVE (${r.reason}) — strict ship mode fails closed.\n` +
            `   Remedy: ${remedy} (completed verdicts are cached).`
        : `guard-review: ${r.name} inconclusive — ${r.reason} (fail-open, not cached)`,
    );
    if (cause === 'response-contract' && r.transcript) console.error(r.transcript.trim());
  }
  if (inconclusive.length > 0) return finish(strict ? 3 : 2);
  return finish(0);
}

